# convert zeros in non-singleton 4-connected components
from collections import deque
h,w=len(grid),len(grid[0]); seen=set(); out=[row[:] for row in grid]
components=[]
for r in range(h):
 for c in range(w):
  if grid[r][c]==0 and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
